-- Whitelist class-data backfill (idempotent).
-- Backfills department / year_or_semester / section and canonical
-- external_id + student_id for whitelist rows created without class
-- data (e.g. CLERK-provisioned registrations), then inserts any
-- students that are missing from the whitelist entirely.
-- Safe to re-run: UPDATE matches by email; INSERT only when the email is absent.

CREATE TEMP TABLE seed_whitelist (
  external_id text, student_id text, name text, email text,
  official_email text, current_login_email text, department text,
  year_or_semester text, section text
) ON COMMIT DROP;


-- 1) Backfill class data into existing rows, preserving passwords/history
UPDATE students s SET
  external_id = sd.external_id,
  student_id = sd.student_id,
  name = sd.name,
  email = sd.email,
  official_email = sd.official_email,
  current_login_email = sd.current_login_email,
  department = sd.department,
  year_or_semester = sd.year_or_semester,
  section = sd.section,
  email_verified = TRUE,
  is_active = TRUE,
  voting_eligible = TRUE,
  updated_at = NOW()
FROM seed_whitelist sd
WHERE LOWER(COALESCE(s.email, '')) = LOWER(sd.email)
   OR LOWER(COALESCE(s.official_email, '')) = LOWER(sd.email)
   OR LOWER(COALESCE(s.current_login_email, '')) = LOWER(sd.email);

-- 2) Insert students missing from the whitelist
SELECT sd.external_id, sd.student_id, sd.name, sd.email, sd.official_email, sd.current_login_email, TRUE, sd.department, sd.year_or_semester, sd.section, TRUE, TRUE, 'STUDENT', NOW(), NOW()
FROM seed_whitelist sd
WHERE NOT EXISTS (
  SELECT 1 FROM students s
  WHERE LOWER(COALESCE(s.email, '')) = LOWER(sd.email)
     OR LOWER(COALESCE(s.official_email, '')) = LOWER(sd.email)
     OR LOWER(COALESCE(s.current_login_email, '')) = LOWER(sd.email)
);

